import React, { useState, useEffect } from 'react';
import { newsletterApi, ApiError } from './services/api';
import { ProcessingStage, AppState } from './types/newsletter';
import TopicInput from './components/Newsletter/TopicInput';
import ProcessingStages from './components/Newsletter/ProcessingStages';
import NewsletterOutput from './components/Newsletter/NewsletterOutput';
import QualityScore from './components/Newsletter/QualityScore';
import './styles/globals.css';

// Define the 5-stage processing pipeline (this remains unchanged)
const initialStages: ProcessingStage[] = [
  {
    id: 'search-planning',
    name: 'Smart Search Planning',
    description: 'AI analyzes your topic and creates targeted search strategies',
    icon: '🧠',
    status: 'pending'
  },
  {
    id: 'content-research',
    name: 'Content Research',
    description: 'Searching the web for the latest and most relevant information',
    icon: '🔍',
    status: 'pending'
  },
  {
    id: 'newsletter-creation',
    name: 'Newsletter Creation',
    description: 'Crafting your professional newsletter with AI-powered writing',
    icon: '✍️',
    status: 'pending'
  },
  {
    id: 'quality-assessment',
    name: 'Quality Assessment',
    description: 'Evaluating newsletter quality across multiple metrics',
    icon: '📊',
    status: 'pending'
  },
  {
    id: 'auto-improvement',
    name: 'Auto-Improvement',
    description: 'Refining and enhancing the newsletter for maximum impact',
    icon: '🔧',
    status: 'pending'
  }
];

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>({
    isGenerating: false,
    currentStage: 0,
    stages: initialStages,
    newsletter: null,
    error: null,
    topic: ''
  });

  const [apiHealth, setApiHealth] = useState<boolean | null>(null);
  // REMOVED: showHero state is no longer needed for the simpler layout.
  // const [showHero, setShowHero] = useState(true);

  // Check API health on component mount
  useEffect(() => {
    checkApiHealth();
  }, []);

  const checkApiHealth = async () => {
    try {
      const isHealthy = await newsletterApi.testConnection();
      setApiHealth(isHealthy);
    } catch (error) {
      setApiHealth(false);
    }
  };

  const resetState = () => {
    setAppState({
      isGenerating: false,
      currentStage: 0,
      stages: initialStages.map(stage => ({ ...stage, status: 'pending' })),
      newsletter: null,
      error: null,
      topic: ''
    });
    // REMOVED: No need to set showHero anymore
  };

  const updateStageStatus = (stageIndex: number, status: ProcessingStage['status'], duration?: number) => {
    setAppState(prev => ({
      ...prev,
      stages: prev.stages.map((stage, index) => 
        index === stageIndex 
          ? { 
              ...stage, 
              status, 
              duration,
              endTime: status === 'completed' ? new Date() : stage.endTime,
              startTime: status === 'processing' ? new Date() : stage.startTime
            }
          : stage
      ),
      currentStage: status === 'completed' ? stageIndex + 1 : stageIndex
    }));
  };

  const simulateProcessingStages = async () => {
    const stageDurations = [2.3, 18.7, 12.1, 3.8, 11.2]; // Realistic durations
    
    for (let i = 0; i < initialStages.length; i++) {
      updateStageStatus(i, 'processing');
      await new Promise(resolve => setTimeout(resolve, 1000)); // Visual feedback delay
      updateStageStatus(i, 'completed', stageDurations[i]);
      if (i < initialStages.length - 1) {
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }
  };

  const handleTopicSubmit = async (topic: string) => {
    // REMOVED: No need to set showHero anymore
    setAppState(prev => ({
      ...prev,
      isGenerating: true,
      topic,
      error: null,
      newsletter: null,
      currentStage: 0,
      stages: initialStages.map(stage => ({ ...stage, status: 'pending' }))
    }));

    try {
      const processingPromise = simulateProcessingStages();
      const apiPromise = newsletterApi.generateNewsletter(topic);
      const [newsletter] = await Promise.all([apiPromise, processingPromise]);
      
      setAppState(prev => ({
        ...prev,
        isGenerating: false,
        newsletter,
        error: null
      }));

    } catch (error) {
      const apiError = error as ApiError;
      setAppState(prev => ({
        ...prev,
        isGenerating: false,
        error: apiError.detail || 'An unexpected error occurred',
        stages: prev.stages.map((stage, index) => 
          index === prev.currentStage 
            ? { ...stage, status: 'error' }
            : stage
        )
      }));
    }
  };

  const handleGenerateAnother = () => {
    resetState();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // REMOVED: scrollToGenerator function is no longer needed.

  return (
    <div className="min-h-screen bg-gray-50">
      {/* --- Navigation --- */}
      <nav className="fixed top-0 w-full bg-white/95 backdrop-blur-md shadow-sm border-b border-gray-200 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center">
              <div className="text-2xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent mr-3">
                🚀
              </div>
              <div>
                <h1 className="text-xl font-bold text-gray-900">
                  Scout AI
                </h1>
                <p className="text-sm text-gray-600">
                  Newsletter Generator
                </p>
              </div>
            </div>
            
            {/* --- API Health Indicator --- */}
            <div className="flex items-center space-x-4">
              {apiHealth === null ? (
                <div className="flex items-center text-gray-500">
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-pulse mr-2"></div>
                  <span className="text-sm">Connecting...</span>
                </div>
              ) : apiHealth ? (
                <div className="flex items-center text-green-600">
                  <div className="w-2 h-2 bg-green-500 rounded-full mr-2"></div>
                  <span className="text-sm font-medium">Online</span>
                </div>
              ) : (
                <div className="flex items-center text-red-600">
                  <div className="w-2 h-2 bg-red-500 rounded-full mr-2"></div>
                  <span className="text-sm font-medium">Offline</span>
                  <button 
                    onClick={checkApiHealth}
                    className="ml-2 text-xs bg-red-100 hover:bg-red-200 text-red-700 px-2 py-1 rounded"
                  >
                    Retry
                  </button>
                </div>
              )}
              {/* REMOVED: The "Try Now" button in the nav bar is gone. */}
            </div>
          </div>
        </div>
      </nav>

      {/* REMOVED: The entire Hero Section and Features Section were here. */}
      {/* The app now jumps directly to the main content. */}

      {/* --- Main Content --- */}
      <main className="pt-24 pb-20 bg-gray-50" id="generator-section">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          {/* Error Message */}
          {appState.error && (
            <div className="mb-8 bg-red-50 border border-red-200 rounded-xl p-6">
              <div className="flex items-center">
                <svg className="w-6 h-6 text-red-600 mr-3" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                </svg>
                <div>
                  <h3 className="text-red-900 font-semibold text-lg">Generation Failed</h3>
                  <p className="text-red-800">{appState.error}</p>
                </div>
              </div>
              <button
                onClick={resetState}
                className="mt-4 bg-red-600 hover:bg-red-700 text-white px-6 py-3 rounded-lg font-semibold transition-colors"
              >
                Try Again
              </button>
            </div>
          )}

          {/* Topic Input - Shows when no newsletter is generated yet */}
          {!appState.newsletter && (
            <TopicInput 
              onSubmit={handleTopicSubmit}
              isLoading={appState.isGenerating}
              disabled={apiHealth === false}
            />
          )}

          {/* Processing Stages - Shows during and after generation */}
          {(appState.isGenerating || appState.newsletter) && (
            <ProcessingStages 
              stages={appState.stages}
              currentStage={appState.currentStage}
              isProcessing={appState.isGenerating}
            />
          )}

          {/* Newsletter Output - Shows after generation is complete */}
          {appState.newsletter && (
            <div className="space-y-8">
              <NewsletterOutput 
                newsletter={appState.newsletter}
                onNewsletter={handleGenerateAnother}
              />
              <QualityScore 
                qualityCheck={appState.newsletter.quality_check}
              />
            </div>
          )}
        </div>
      </main>

      {/* REMOVED: The footer was here. You can add a simpler one back if you like. */}
    </div>
  );
};

export default App;
